function K.ChatText(key)
 local lang=K.account and K.account.language or KAClassic_KerimAnkaUIDB and KAClassic_KerimAnkaUIDB.language or 'en'
 return (translations[lang]or translations.en)[key]or key
end
for lang,values in pairs(translations)do
 K.locales[lang]=K.locales[lang]or{}
 for key,value in pairs(values)do K.locales[lang][key]=value end
 K.locales[lang].chat=values['Chat and Micro Menu']
end
